package com.easyperformance.program;
import com.easyperformance.program.ProgramTypes.SubmissionStatus;import com.easyware.platform.UuidV7;import com.easyware.platform.audit.TenantAwareAuditEntity;import jakarta.persistence.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="program_intermediate_review",uniqueConstraints=@UniqueConstraint(name="uq_program_intermediate_participant",columnNames={"tenant_id","participant_id"}))
public class ProgramIntermediateReview extends TenantAwareAuditEntity{
 @Id @Column(columnDefinition="uuid",nullable=false,updatable=false)private UUID id;@Column(name="program_id",columnDefinition="uuid",nullable=false)private UUID programId;@Column(name="participant_id",columnDefinition="uuid",nullable=false)private UUID participantId;@Column(name="checker_employee_id",columnDefinition="uuid",nullable=false)private UUID checkerEmployeeId;@Column(nullable=false,columnDefinition="text")private String opinion;@JdbcTypeCode(SqlTypes.JSON)@Column(name="task_evidence",columnDefinition="jsonb",nullable=false)private String taskEvidence;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private SubmissionStatus status;@Column(name="completed_at")private Instant completedAt;@Version@Column(name="row_version",nullable=false)private long rowVersion;
 @PrePersist void prePersist(){if(id==null)id=UuidV7.generate();if(status==null)status=SubmissionStatus.DRAFT;}public UUID getId(){return id;}public void setId(UUID v){id=v;}public UUID getProgramId(){return programId;}public void setProgramId(UUID v){programId=v;}public UUID getParticipantId(){return participantId;}public void setParticipantId(UUID v){participantId=v;}public UUID getCheckerEmployeeId(){return checkerEmployeeId;}public void setCheckerEmployeeId(UUID v){checkerEmployeeId=v;}public String getOpinion(){return opinion;}public void setOpinion(String v){opinion=v;}public String getTaskEvidence(){return taskEvidence;}public void setTaskEvidence(String v){taskEvidence=v;}public SubmissionStatus getStatus(){return status;}public void setStatus(SubmissionStatus v){status=v;}public Instant getCompletedAt(){return completedAt;}public void setCompletedAt(Instant v){completedAt=v;}public long getRowVersion(){return rowVersion;}
}
